    ["2026-12-09", L3("Federal Assembly elects Guy Parmelin's successor; the SVP group picks its ticket on 20 November.", "L'Assemblée fédérale élit le successeur de Guy Parmelin ; le groupe UDC choisit son ticket le 20 novembre.", "La Asamblea Federal elige al sucesor de Guy Parmelin; el grupo de la SVP elige su candidatura el 20 de noviembre."), U.brWahl],
    [null, L3("Winter session: the National Council must finish the institutional part of the EU package; whether a majority of cantons is required is still open.", "Session d'hiver : le Conseil national doit boucler la partie institutionnelle du paquet européen ; la question de la double majorité des cantons reste ouverte.", "Sesión de invierno: el Consejo Nacional debe terminar la parte institucional del paquete europeo; sigue abierto si hará falta la mayoría de cantones."), U.eu26],
    [null, L3("Prosecutors in Aargau may investigate SVP MP Andreas Glarner for suspected misuse of identity over a deepfake video of Green MP Sibel Arslan (immunity lifted June 2025); presumption of innocence applies.", "Le parquet argovien peut enquêter sur le conseiller national UDC Andreas Glarner pour usurpation d'identité présumée liée à une vidéo truquée de la conseillère nationale verte Sibel Arslan (immunité levée en juin 2025) ; présomption d'innocence.", "La fiscalía de Argovia puede investigar al diputado de la SVP Andreas Glarner por presunta usurpación de identidad por un vídeo manipulado de la diputada verde Sibel Arslan (inmunidad levantada en junio de 2025); rige la presunción de inocencia."), U.glarnerRK],
    ["2027-06-06", L3("Planned popular vote on the institutional ('stabilisation') part of the EU treaty package.", "Votation prévue sur la partie institutionnelle (« stabilisation ») du paquet d'accords avec l'UE.", "Votación prevista sobre la parte institucional («estabilización») del paquete de acuerdos con la UE."), U.eu26],
    ["2027-10-24", L3("Federal elections: National Council and Council of States.", "Élections fédérales : Conseil national et Conseil des États.", "Elecciones federales: Consejo Nacional y Consejo de los Estados."), U.wahlen27]
